import React from "react";
import { Link } from "react-router-dom";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "linear-gradient(135deg, #ffe3f1, #d9f8ff, #fff7d6)",
        padding: "60px 20px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      {/* HERO SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "auto",
          padding: "130px 20px",
          borderRadius: "40px",
          textAlign: "center",
          background: "linear-gradient(135deg, #ffb6d9, #a0e7ff)",
          boxShadow: "0 30px 60px rgba(0,0,0,0.12)",
        }}
      >
        <h1
          style={{
            fontSize: "52px",
            color: "white",
            marginBottom: "20px",
            fontWeight: "700",
          }}
        >
          Nanhe Farishte – Kiran Knits
        </h1>

        <p
          style={{
            fontSize: "22px",
            color: "white",
            marginBottom: "40px",
            opacity: "0.95",
          }}
        >
          Har bunai mein maa ka pyaar 💖
        </p>

        <Link to="/products">
          <button
            style={{
              background: "white",
              border: "none",
              padding: "16px 50px",
              borderRadius: "50px",
              color: "#ff4f87",
              fontSize: "18px",
              fontWeight: "600",
              cursor: "pointer",
              transition: "0.3s ease",
              boxShadow: "0 10px 30px rgba(0,0,0,0.2)",
            }}
            onMouseOver={(e) => {
              e.target.style.transform = "scale(1.1)";
              e.target.style.background = "#ff4f87";
              e.target.style.color = "white";
            }}
            onMouseOut={(e) => {
              e.target.style.transform = "scale(1)";
              e.target.style.background = "white";
              e.target.style.color = "#ff4f87";
            }}
          >
            ✨ Shop Now
          </button>
        </Link>
      </div>

      {/* CATEGORY SECTION */}
      <div
        style={{
          maxWidth: "1100px",
          margin: "100px auto 0",
          textAlign: "center",
        }}
      >
        <h2
          style={{
            fontSize: "34px",
            marginBottom: "60px",
            color: "#444",
          }}
        >
          Our Categories
        </h2>

        <div
          style={{
            display: "flex",
            justifyContent: "center",
            gap: "50px",
            flexWrap: "wrap",
          }}
        >
          <CategoryCard emoji="🧥" title="Sweaters" link="/products?category=Sweater" />
          <CategoryCard emoji="🧦" title="Socks" link="/products?category=Socks" />
          <CategoryCard emoji="🧢" title="Caps" link="/products?category=Cap" />
        </div>
      </div>
    </div>
  );
};

const CategoryCard = ({ emoji, title, link }) => {
  return (
    <Link to={link} style={{ textDecoration: "none" }}>
      <div
        style={{
          background: "white",
          padding: "70px 40px",
          borderRadius: "30px",
          width: "240px",
          fontSize: "24px",
          fontWeight: "600",
          color: "#444",
          boxShadow: "0 20px 40px rgba(0,0,0,0.1)",
          transition: "0.3s ease",
          cursor: "pointer",
        }}
        onMouseOver={(e) => {
          e.currentTarget.style.transform = "translateY(-15px) scale(1.05)";
          e.currentTarget.style.background =
            "linear-gradient(135deg, #ffe0f0, #e0f7ff)";
        }}
        onMouseOut={(e) => {
          e.currentTarget.style.transform = "translateY(0) scale(1)";
          e.currentTarget.style.background = "white";
        }}
      >
        <div style={{ fontSize: "45px", marginBottom: "15px" }}>
          {emoji}
        </div>
        {title}
      </div>
    </Link>
  );
};

export default Home;
